import{_ as e,o as a,c as d,a3 as s}from"./chunks/framework.BlfGB29P.js";const k=JSON.parse('{"title":"全局属性与自定义属性","description":"","frontmatter":{"title":"全局属性与自定义属性","outline":[2,3],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"frontend/guide/core/web/html/global-custom-attributes.md","filePath":"frontend/guide/core/web/html/global-custom-attributes.md","lastUpdated":1785217527000}'),i={name:"frontend/guide/core/web/html/global-custom-attributes.md"};function n(l,t,o,r,h,c){return a(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="全局属性与自定义属性" tabindex="-1">全局属性与自定义属性 <a class="header-anchor" href="#全局属性与自定义属性" aria-label="Permalink to &quot;全局属性与自定义属性&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>全局属性可以写在所有 HTML 元素上，但“语法允许”不代表“放在哪里都有实际作用”。例如，<code>inputmode</code> 只有作用于表单控件或可编辑宿主时才会影响虚拟键盘，<code>title</code> 也不能替代可见标签和帮助文本。</p><p>本篇梳理全局属性、content attribute 与 DOM property 的关系，以及应用私有数据、ARIA、Microdata 和 Web Components 属性的边界。</p><h2 id="_1-content-attribute-与-dom-property" tabindex="-1">1. Content attribute 与 DOM property <a class="header-anchor" href="#_1-content-attribute-与-dom-property" aria-label="Permalink to &quot;1. Content attribute 与 DOM property&quot;">​</a></h2><p>HTML 源码中的属性称为 content attribute；JavaScript 对象上的字段通常称为 IDL attribute 或 DOM property。</p><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">article</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;task-42&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> lang</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;zh-CN&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> data-state</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pending&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">article</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> article</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> document.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">querySelector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;#task-42&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">article.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getAttribute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;lang&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// &quot;zh-CN&quot;，读取 content attribute</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">article.lang                 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// &quot;zh-CN&quot;，读取反射后的 DOM property</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">article.dataset.state        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// &quot;pending&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>两者并不总是相同：</p><ul><li>content attribute 在源码中是文本。</li><li>DOM property 可以是字符串、布尔值、数字、对象或枚举状态。</li><li>有些 property 会反射属性，修改一方会更新另一方。</li><li>有些 property 只表示运行时状态，不直接对应同名 HTML 属性。</li><li>属性的缺失值、空字符串和非法值可能由标准映射到不同状态。</li></ul><h3 id="_1-1-属性操作-api" tabindex="-1">1.1 属性操作 API <a class="header-anchor" href="#_1-1-属性操作-api" aria-label="Permalink to &quot;1.1 属性操作 API&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途</th><th>注意点</th></tr></thead><tbody><tr><td><code>hasAttribute(name)</code></td><td>判断属性是否存在</td><td>返回布尔值</td></tr><tr><td><code>getAttribute(name)</code></td><td>读取属性源码值</td><td>不存在时返回 <code>null</code></td></tr><tr><td><code>setAttribute(name, value)</code></td><td>写入属性</td><td>值会转换成字符串</td></tr><tr><td><code>removeAttribute(name)</code></td><td>删除属性</td><td>适合恢复缺失状态</td></tr><tr><td><code>toggleAttribute(name, force?)</code></td><td>切换属性是否存在</td><td>适合布尔属性</td></tr><tr><td><code>getAttributeNames()</code></td><td>获取所有属性名</td><td>返回字符串数组</td></tr><tr><td><code>attributes</code></td><td>获取 <code>NamedNodeMap</code></td><td>实时集合，常用于检查与序列化</td></tr></tbody></table><p>对于已知语义属性，优先使用类型更明确的 property，例如 <code>input.disabled</code>、<code>element.inert</code>；编写通用属性工具或处理未知 <code>data-*</code> 时，再使用属性方法。</p><h2 id="_2-属性值类型" tabindex="-1">2. 属性值类型 <a class="header-anchor" href="#_2-属性值类型" aria-label="Permalink to &quot;2. 属性值类型&quot;">​</a></h2><h3 id="_2-1-字符串属性" tabindex="-1">2.1 字符串属性 <a class="header-anchor" href="#_2-1-字符串属性" aria-label="Permalink to &quot;2.1 字符串属性&quot;">​</a></h3><p><code>id</code>、<code>class</code>、<code>title</code>、<code>lang</code> 和多数 URL 属性在源码中使用字符串。</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">element.id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;task-42&#39;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">element.lang </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;zh-CN&#39;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">element.title </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;查看详情&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>字符串属性可能有自己的语法约束。例如 <code>lang</code> 应使用有效语言标签，<code>id</code> 在文档树中应唯一，URL 属性的 DOM property 还可能返回解析后的绝对 URL。</p><h3 id="_2-2-布尔属性" tabindex="-1">2.2 布尔属性 <a class="header-anchor" href="#_2-2-布尔属性" aria-label="Permalink to &quot;2.2 布尔属性&quot;">​</a></h3><p>布尔属性由“是否存在”决定真假，属性文本不是 JavaScript 布尔值：</p><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 两个 section 都是 inert。 --&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">section</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> inert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">section</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">section</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> inert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;false&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">section</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">section.inert </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">section.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">removeAttribute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;inert&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>常见布尔属性包括：</p><ul><li>全局属性：<code>inert</code>、<code>autofocus</code>、<code>itemscope</code>。</li><li>表单属性：<code>disabled</code>、<code>checked</code>、<code>required</code>、<code>multiple</code>、<code>readonly</code>。</li><li>媒体属性：<code>controls</code>、<code>autoplay</code>、<code>loop</code>、<code>muted</code>。</li></ul><p>不要输出 <code>disabled=&quot;false&quot;</code>、<code>checked=&quot;false&quot;</code> 等写法。需要假值时应省略属性。</p><h3 id="_2-3-枚举属性" tabindex="-1">2.3 枚举属性 <a class="header-anchor" href="#_2-3-枚举属性" aria-label="Permalink to &quot;2.3 枚举属性&quot;">​</a></h3><p>枚举属性接受一组关键字，并为缺失、空值和非法值定义状态。</p><table tabindex="0"><thead><tr><th>属性</th><th>主要关键字或状态</th></tr></thead><tbody><tr><td><code>hidden</code></td><td>Hidden、Hidden Until Found、Not Hidden</td></tr><tr><td><code>dir</code></td><td><code>ltr</code>、<code>rtl</code>、<code>auto</code></td></tr><tr><td><code>contenteditable</code></td><td><code>true</code>、空字符串、<code>false</code>、<code>plaintext-only</code></td></tr><tr><td><code>draggable</code></td><td><code>true</code>、<code>false</code></td></tr><tr><td><code>spellcheck</code></td><td><code>true</code>、空字符串、<code>false</code></td></tr><tr><td><code>translate</code></td><td><code>yes</code>、空字符串、<code>no</code></td></tr><tr><td><code>popover</code></td><td><code>auto</code>、<code>hint</code>、<code>manual</code></td></tr></tbody></table><p><code>hidden=&quot;false&quot;</code> 不表示显示。它不是布尔属性，非法关键字仍会进入 Hidden 状态。显示元素应移除属性或把 <code>element.hidden</code> 设置为 <code>false</code>。</p><h2 id="_3-标识与样式属性" tabindex="-1">3. 标识与样式属性 <a class="header-anchor" href="#_3-标识与样式属性" aria-label="Permalink to &quot;3. 标识与样式属性&quot;">​</a></h2><h3 id="_3-1-id" tabindex="-1">3.1 <code>id</code> <a class="header-anchor" href="#_3-1-id" aria-label="Permalink to &quot;3.1 `id`&quot;">​</a></h3><p><code>id</code> 在文档树中应唯一，常用于：</p><ul><li>URL fragment 目标。</li><li><code>label[for]</code>、<code>aria-labelledby</code>、<code>headers</code> 等 ID 引用。</li><li><code>document.getElementById()</code>。</li><li>CSS ID 选择器。</li></ul><p>不要用随机变化的 ID 作为稳定链接目标，也不要依赖浏览器把 ID 暴露为 <code>window</code> 全局变量。</p><h3 id="_3-2-class" tabindex="-1">3.2 <code>class</code> <a class="header-anchor" href="#_3-2-class" aria-label="Permalink to &quot;3.2 `class`&quot;">​</a></h3><p><code>class</code> 是空格分隔的 token 集合，用于样式和脚本分类。</p><table tabindex="0"><thead><tr><th>API</th><th>作用</th></tr></thead><tbody><tr><td><code>element.className</code></td><td>读取或整体设置 class 字符串</td></tr><tr><td><code>classList.add(...tokens)</code></td><td>添加 token</td></tr><tr><td><code>classList.remove(...tokens)</code></td><td>删除 token</td></tr><tr><td><code>classList.toggle(token, force?)</code></td><td>切换 token</td></tr><tr><td><code>classList.replace(old, next)</code></td><td>替换 token</td></tr><tr><td><code>classList.contains(token)</code></td><td>判断是否存在</td></tr></tbody></table><p>class 名称不会增加语义。<code>class=&quot;button&quot;</code> 只提供分类，不会让元素获得按钮角色、焦点和键盘行为。</p><h3 id="_3-3-style" tabindex="-1">3.3 <code>style</code> <a class="header-anchor" href="#_3-3-style" aria-label="Permalink to &quot;3.3 `style`&quot;">​</a></h3><p><code>style</code> 保存元素级 CSS 声明，对应 <code>element.style</code>。它适合必须由运行时计算的少量值，例如尺寸或坐标；稳定的视觉状态通常使用 class、<code>data-*</code> 或 CSS 自定义属性。</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">element.style.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setProperty</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;--progress&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;42%&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">element.style.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">removeProperty</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;--progress&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>大量写入内联样式会提高覆盖成本，也可能违反 CSP。样式组织方式在 CSS 方案与工具分组中展开。</p><h3 id="_3-4-title" tabindex="-1">3.4 <code>title</code> <a class="header-anchor" href="#_3-4-title" aria-label="Permalink to &quot;3.4 `title`&quot;">​</a></h3><p><code>title</code> 提供建议性信息，浏览器可能显示为鼠标悬停提示。它有明显限制：</p><ul><li>键盘、触摸和辅助技术用户不一定能稳定获得。</li><li>不应代替表单标签、按钮名称或可见帮助文本。</li><li>父元素的 title 可能影响后代，空 title 可终止继承。</li></ul><p>需要用户必须知道的信息，应直接显示或通过可靠的可访问描述关联。</p><h2 id="_4-语言与文字方向" tabindex="-1">4. 语言与文字方向 <a class="header-anchor" href="#_4-语言与文字方向" aria-label="Permalink to &quot;4. 语言与文字方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>作用</th><th>典型值</th></tr></thead><tbody><tr><td><code>lang</code></td><td>声明内容语言</td><td><code>zh-CN</code>、<code>en</code>、<code>ja</code></td></tr><tr><td><code>dir</code></td><td>声明文字方向</td><td><code>ltr</code>、<code>rtl</code>、<code>auto</code></td></tr><tr><td><code>translate</code></td><td>声明内容是否应被翻译</td><td><code>yes</code>、<code>no</code></td></tr></tbody></table><p><code>dir=&quot;auto&quot;</code> 适合用户生成且方向未知的短内容。双向文本的局部隔离还可以使用 <code>bdi</code>；必须显式覆盖方向时使用 <code>bdo</code>。</p><p><code>translate=&quot;no&quot;</code> 常用于产品名、代码、用户标识等不应翻译的内容，但翻译工具是否遵循仍取决于实现。</p><h2 id="_5-可见性与交互状态" tabindex="-1">5. 可见性与交互状态 <a class="header-anchor" href="#_5-可见性与交互状态" aria-label="Permalink to &quot;5. 可见性与交互状态&quot;">​</a></h2><h3 id="_5-1-hidden" tabindex="-1">5.1 <code>hidden</code> <a class="header-anchor" href="#_5-1-hidden" aria-label="Permalink to &quot;5.1 `hidden`&quot;">​</a></h3><p><code>hidden</code> 表示内容当前不相关或尚未展示。</p><table tabindex="0"><thead><tr><th>写法</th><th>状态</th></tr></thead><tbody><tr><td><code>hidden</code></td><td>Hidden，不渲染</td></tr><tr><td><code>hidden=&quot;&quot;</code></td><td>Hidden</td></tr><tr><td><code>hidden=&quot;until-found&quot;</code></td><td>初始隐藏，但可由页内查找或 fragment 导航揭示</td></tr><tr><td>缺失属性</td><td>Not Hidden</td></tr></tbody></table><p>CSS 可以意外覆盖浏览器对 <code>hidden</code> 的默认渲染，因此不要写会让所有元素强制 <code>display:block</code> 的宽泛规则。</p><h3 id="_5-2-inert" tabindex="-1">5.2 <code>inert</code> <a class="header-anchor" href="#_5-2-inert" aria-label="Permalink to &quot;5.2 `inert`&quot;">​</a></h3><p><code>inert</code> 使元素的 flat tree 后代不可聚焦、不可交互、不可选择，并通常不暴露给辅助技术。它适合暂时禁用背景页面或尚不可用的整片内容。</p><p><code>inert</code> 本身没有统一视觉效果。使用时必须让视觉状态和交互状态一致，避免用户看到可点击控件却无法操作。</p><h3 id="_5-3-tabindex" tabindex="-1">5.3 <code>tabindex</code> <a class="header-anchor" href="#_5-3-tabindex" aria-label="Permalink to &quot;5.3 `tabindex`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>值</th><th>行为</th></tr></thead><tbody><tr><td>未指定</td><td>由元素原生语义决定是否进入顺序焦点导航</td></tr><tr><td><code>0</code></td><td>进入自然 Tab 顺序</td></tr><tr><td><code>-1</code></td><td>可通过脚本聚焦，但不进入自然 Tab 顺序</td></tr><tr><td>正整数</td><td>创建人工焦点顺序，通常应避免</td></tr></tbody></table><p>不要给所有 <code>div</code> 添加 <code>tabindex=&quot;0&quot;</code>。可聚焦不等于可操作，原生交互元素或完整自定义组件还需要正确角色、键盘行为和状态。</p><h3 id="_5-4-其他交互属性" tabindex="-1">5.4 其他交互属性 <a class="header-anchor" href="#_5-4-其他交互属性" aria-label="Permalink to &quot;5.4 其他交互属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th></tr></thead><tbody><tr><td><code>accesskey</code></td><td>声明访问键，但平台组合方式不一致，不能作为唯一入口</td></tr><tr><td><code>autofocus</code></td><td>页面或弹层显示时请求焦点，需避免抢夺用户焦点</td></tr><tr><td><code>popover</code></td><td>把元素声明为 popover，详见交互章节</td></tr></tbody></table><h2 id="_6-编辑、输入与拖放提示" tabindex="-1">6. 编辑、输入与拖放提示 <a class="header-anchor" href="#_6-编辑、输入与拖放提示" aria-label="Permalink to &quot;6. 编辑、输入与拖放提示&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>作用</th><th>关键边界</th></tr></thead><tbody><tr><td><code>contenteditable</code></td><td>把元素设为富文本或纯文本编辑宿主</td><td>不自动提供数据模型、撤销策略和安全过滤</td></tr><tr><td><code>spellcheck</code></td><td>提示是否进行拼写和语法检查</td><td>用户代理可以覆盖</td></tr><tr><td><code>autocapitalize</code></td><td>提示虚拟键盘自动大写策略</td><td>不负责数据校验</td></tr><tr><td><code>autocorrect</code></td><td>提示是否自动更正</td><td>支持与行为依赖平台</td></tr><tr><td><code>inputmode</code></td><td>提示虚拟键盘类型</td><td>不限制实际输入值</td></tr><tr><td><code>enterkeyhint</code></td><td>提示虚拟键盘回车键文案或图标</td><td>仅影响输入体验</td></tr><tr><td><code>writingsuggestions</code></td><td>控制浏览器书写建议</td><td>使用前检查目标浏览器</td></tr><tr><td><code>draggable</code></td><td>声明原生拖放状态</td><td>是枚举属性，必须写 <code>true</code> 或 <code>false</code></td></tr></tbody></table><p><code>contenteditable</code> 会引入选区、剪贴板、输入法、HTML 清理和撤销栈等完整编辑问题。复杂富文本不应只依赖一个属性完成。</p><h2 id="_7-data-与-dataset" tabindex="-1">7. <code>data-*</code> 与 <code>dataset</code> <a class="header-anchor" href="#_7-data-与-dataset" aria-label="Permalink to &quot;7. `data-*` 与 `dataset`&quot;">​</a></h2><p><code>data-*</code> 用于保存页面或应用私有数据：</p><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">article</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> data-task-id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;T-42&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> data-state</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pending&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">article</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> article</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> document.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">querySelector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;article&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">article.dataset.taskId       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// &quot;T-42&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">article.dataset.state        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// &quot;pending&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">article.dataset.state </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;done&#39;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">delete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> article.dataset.state</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>名称转换规则：</p><table tabindex="0"><thead><tr><th>HTML 属性</th><th><code>dataset</code> 属性</th></tr></thead><tbody><tr><td><code>data-task-id</code></td><td><code>dataset.taskId</code></td></tr><tr><td><code>data-user-name</code></td><td><code>dataset.userName</code></td></tr><tr><td><code>data-index-number</code></td><td><code>dataset.indexNumber</code></td></tr></tbody></table><p>所有值都按字符串处理：</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">article.dataset.count </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     // 实际写入 &quot;3&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">article.dataset.value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 实际写入 &quot;null&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>删除值应使用 <code>delete</code> 或 <code>removeAttribute()</code>。读取外部或不可信 DOM 时，可使用 <code>Object.hasOwn(article.dataset, &#39;state&#39;)</code> 判断自有键。</p><p><code>data-*</code> 不适合：</p><ul><li>保存敏感信息。它对页面脚本和开发者工具完全可见。</li><li>保存大型 JSON 状态。复杂状态应放在应用数据层。</li><li>替代原生属性。禁用按钮应使用 <code>disabled</code>，不是 <code>data-disabled</code>。</li><li>替代可访问性状态。展开状态使用 <code>aria-expanded</code>。</li></ul><h2 id="_8-其他属性体系" tabindex="-1">8. 其他属性体系 <a class="header-anchor" href="#_8-其他属性体系" aria-label="Permalink to &quot;8. 其他属性体系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性体系</th><th>解决的问题</th><th>使用边界</th></tr></thead><tbody><tr><td><code>role</code>、<code>aria-*</code></td><td>补充可访问性角色、名称、状态和关系</td><td>不实现键盘与交互行为；原生 HTML 优先</td></tr><tr><td><code>itemscope</code>、<code>itemprop</code> 等</td><td>Microdata 结构化实体</td><td>不保存组件运行状态</td></tr><tr><td><code>slot</code>、<code>part</code>、<code>exportparts</code></td><td>Web Component 内容分发与样式接口</td><td>应作为稳定的公共组件契约</td></tr><tr><td><code>nonce</code></td><td>允许 CSP 验证特定内联脚本或样式</td><td>必须由服务端逐响应随机生成</td></tr><tr><td><code>onclick</code>、<code>oninput</code> 等</td><td>在属性中注册事件处理器</td><td>工程代码通常使用 <code>addEventListener()</code> 或框架事件绑定</td></tr></tbody></table><p>这些属性虽然都写在开始标签中，但服务对象不同。应用私有状态使用 <code>data-*</code>，辅助技术状态使用 ARIA，组件公开接口使用稳定属性；不能因为语法相似就互相替代。</p><h2 id="_9-常见误区" tabindex="-1">9. 常见误区 <a class="header-anchor" href="#_9-常见误区" aria-label="Permalink to &quot;9. 常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>正确理解</th></tr></thead><tbody><tr><td>全局属性在所有元素上都有同样效果</td><td>许多属性只在特定上下文生效</td></tr><tr><td><code>disabled=&quot;false&quot;</code> 表示启用</td><td>布尔属性存在即为真</td></tr><tr><td><code>hidden=&quot;false&quot;</code> 表示显示</td><td>该值仍进入 Hidden 状态</td></tr><tr><td><code>inputmode=&quot;numeric&quot;</code> 会阻止非数字输入</td><td>它只提示虚拟键盘类型</td></tr><tr><td><code>title</code> 可以替代可见标签</td><td>title 的可发现性和设备支持不足</td></tr><tr><td><code>data-*</code> 可以保存任意应用状态</td><td>它只适合少量、非敏感、元素相关字符串数据</td></tr><tr><td><code>aria-*</code> 和 <code>data-*</code> 可以互换</td><td>ARIA 面向辅助技术，data 面向应用</td></tr><tr><td>给 <code>div</code> 加 <code>tabindex</code> 就完成了组件</td><td>还缺少角色、名称、键盘和状态行为</td></tr></tbody></table><h2 id="_10-总结" tabindex="-1">10. 总结 <a class="header-anchor" href="#_10-总结" aria-label="Permalink to &quot;10. 总结&quot;">​</a></h2><p>全局属性提供跨元素共享的语言、标识、编辑、可见性和交互能力；专用属性则由具体元素定义。读取属性时需要区分源码字符串和 DOM property，尤其注意布尔属性、枚举属性和运行时状态。</p><p>应用私有数据使用 <code>data-*</code>，可访问性状态使用 ARIA，结构化实体使用 Microdata，Shadow DOM 内容分发与样式接口使用 <code>slot</code> 和 <code>part</code>。不同属性体系解决不同问题，不应因为它们都写在开始标签中就混为一类。</p><h2 id="_11-标准与参考" tabindex="-1">11. 标准与参考 <a class="header-anchor" href="#_11-标准与参考" aria-label="Permalink to &quot;11. 标准与参考&quot;">​</a></h2><ul><li><a href="https://html.spec.whatwg.org/dev/dom.html#global-attributes" target="_blank" rel="noreferrer">HTML Living Standard：Global attributes</a></li><li><a href="https://html.spec.whatwg.org/dev/interaction.html#the-hidden-attribute" target="_blank" rel="noreferrer">HTML Living Standard：The hidden attribute</a></li><li><a href="https://html.spec.whatwg.org/dev/interaction.html#inert-subtrees" target="_blank" rel="noreferrer">HTML Living Standard：Inert subtrees</a></li><li><a href="https://html.spec.whatwg.org/dev/custom-elements.html" target="_blank" rel="noreferrer">HTML Living Standard：Custom elements</a></li></ul>',87)])])}const u=e(i,[["render",n]]);export{k as __pageData,u as default};
